@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2 class="mb-4">Dispatcher Dashboard</h2>

<div class="row mb-3 g-2">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking # or destination..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-secondary w-100" @onclick="ResetFilters">Clear Filters</button>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <div class="alert alert-info">No shipments match your filters.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @StatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <select class="form-select form-select-sm d-inline-block w-auto"
                                        value="@s.Status"
                                        @onchange="e => UpdateStatus(s, e)">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status">@status</option>
                                    }
                                </select>
                            }
                            else
                            {
                                <span class="text-muted">—</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger mt-3">@errorMessage</div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;
    private string? errorMessage;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
        {
            if (!string.IsNullOrWhiteSpace(statusFilter)
                && Enum.TryParse<ShipmentStatus>(statusFilter, out var filter)
                && s.Status != filter)
                return false;

            if (!string.IsNullOrWhiteSpace(searchTerm)
                && !s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
                && !s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
                return false;

            return true;
        });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
            errorMessage = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            try
            {
                var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
                var index = shipments!.FindIndex(s => s.Id == shipment.Id);
                if (index >= 0)
                    shipments[index] = updated;
                errorMessage = null;
            }
            catch (Exception ex)
            {
                errorMessage = $"Failed to update status: {ex.Message}";
            }
        }
    }

    private void ResetFilters()
    {
        searchTerm = string.Empty;
        statusFilter = string.Empty;
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2 class="mb-4">Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. ST-10001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@isSearching">
                @if (isSearching)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Search
            </button>
        </div>
    </div>
</div>

@if (searched && shipment is null && !isSearching)
{
    <div class="alert alert-warning">
        No shipment found for tracking number <strong>@lastSearched</strong>. Please check the number and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h4 class="mb-0">@shipment.TrackingNumber</h4>
            <span class="badge fs-6 @StatusBadgeClass(shipment.Status)">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-6">
                    <h6 class="text-muted">Route</h6>
                    <p class="fs-5">@shipment.Origin → @shipment.Destination</p>
                </div>
                <div class="col-md-6">
                    <h6 class="text-muted">Recipient</h6>
                    <p class="fs-5">@shipment.RecipientName</p>
                </div>
                <div class="col-md-4">
                    <h6 class="text-muted">Shipped</h6>
                    <p>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                </div>
                <div class="col-md-4">
                    <h6 class="text-muted">Estimated Delivery</h6>
                    <p class="fw-bold @(IsOverdue ? "text-danger" : "")">
                        @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")
                        @if (IsOverdue)
                        {
                            <span> (overdue)</span>
                        }
                    </p>
                </div>
                <div class="col-md-4">
                    <h6 class="text-muted">Actual Delivery</h6>
                    <p>@(shipment.ActualDelivery?.ToString("MMMM dd, yyyy") ?? "—")</p>
                </div>
                <div class="col-12">
                    <h6 class="text-muted">Description</h6>
                    <p>@shipment.Description</p>
                </div>
            </div>

            <hr />
            <h6 class="text-muted mb-3">Shipment Progress</h6>
            <div class="d-flex justify-content-between position-relative mb-3">
                @foreach (var step in progressSteps)
                {
                    var reached = (int)shipment.Status >= (int)step;
                    <div class="text-center flex-fill">
                        <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(reached ? "bg-success" : "bg-secondary bg-opacity-25")"
                             style="width: 36px; height: 36px;">
                            @if (reached)
                            {
                                <span class="text-white">✓</span>
                            }
                        </div>
                        <div class="small mt-1 @(reached ? "fw-bold" : "text-muted")">@step</div>
                    </div>
                }
            </div>
        </div>
    </div>
}

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger mt-3">@errorMessage</div>
}

@code {
    private string trackingNumber = string.Empty;
    private string? lastSearched;
    private ShipmentDto? shipment;
    private bool searched;
    private bool isSearching;
    private string? errorMessage;

    private static readonly ShipmentStatus[] progressSteps =
    [
        ShipmentStatus.Pending,
        ShipmentStatus.PickedUp,
        ShipmentStatus.InTransit,
        ShipmentStatus.OutForDelivery,
        ShipmentStatus.Delivered
    ];

    private bool IsOverdue =>
        shipment is not null
        && shipment.Status != ShipmentStatus.Delivered
        && shipment.Status != ShipmentStatus.Cancelled
        && shipment.EstimatedDelivery < DateTime.UtcNow;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        isSearching = true;
        errorMessage = null;

        try
        {
            lastSearched = trackingNumber.Trim();
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
            searched = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Error looking up shipment: {ex.Message}";
        }
        finally
        {
            isSearching = false;
        }
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
