                    var reached = (int)shipment.Status >= (int)step;
                    <div class="text-center flex-fill">
                        <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(reached ? "bg-success" : "bg-secondary bg-opacity-25")"
                             style="width: 36px; height: 36px;">
                            @if (reached)
                            {
                                <span class="text-white">✓</span>
                            }
                        </div>
                        <div class="small mt-1 @(reached ? "fw-bold" : "text-muted")">@step</div>
                    </div>
                }
            </div>
        </div>
    </div>
}

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger mt-3">@errorMessage</div>
}

@code {
    private string trackingNumber = string.Empty;
    private string? lastSearched;
    private ShipmentDto? shipment;
    private bool searched;
    private bool isSearching;
    private string? errorMessage;

    private static readonly ShipmentStatus[] progressSteps =
    [
        ShipmentStatus.Pending,
        ShipmentStatus.PickedUp,
        ShipmentStatus.InTransit,
        ShipmentStatus.OutForDelivery,
        ShipmentStatus.Delivered
    ];

    private bool IsOverdue =>
        shipment is not null
        && shipment.Status != ShipmentStatus.Delivered
        && shipment.Status != ShipmentStatus.Cancelled
        && shipment.EstimatedDelivery < DateTime.UtcNow;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        isSearching = true;
        errorMessage = null;

        try
        {
            lastSearched = trackingNumber.Trim();
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
            searched = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Error looking up shipment: {ex.Message}";
        }
        finally
        {
            isSearching = false;
        }
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dispatcher"
@using ShipmentTracker.Client.Models
